	}
	fresh[f.Path] = f.Type
}

mutations.replace:
fresh := map[string]string{}
for _, f := range transcript.FieldsOfObserved(x.Res.Body, IsRedacted) {
	if isRootPath(f.Path) && false {
		continue
	}
	fresh[f.Path] = f.Type
}

